yt-confirm-dialog-renderer {
    background: #ffffff !important;
    background-color: #ffffff !important;
    color: var(--ytm-light-text) !important;
}

tp-yt-paper-dialog yt-formatted-string,
ytmusic-popup-container yt-formatted-string,
yt-confirm-dialog-renderer yt-formatted-string {
    color: var(--ytm-light-text) !important;
}


/* =========================================================
   29. SETTINGS
   ========================================================= */

ytmusic-settings-page,
ytmusic-setting-category-collection-renderer,
ytmusic-setting-single-option-menu-renderer {
    background: #ffffff !important;
    background-color: #ffffff !important;
    color: var(--ytm-light-text) !important;
}

ytmusic-settings-page .category-menu {
    background: var(--ytm-light-surface) !important;
}

ytmusic-settings-page .category-menu-item:hover {
    background: var(--ytm-light-hover) !important;
}

ytmusic-settings-page .category-menu-item.iron-selected {
    background: var(--ytm-light-selected) !important;
}


/* =========================================================
   30. TOASTS / NOTIFICATIONS
   ========================================================= */

tp-yt-paper-toast,
ytmusic-notification-text-renderer {
    background: #ffffff !important;
    background-color: #ffffff !important;
    color: var(--ytm-light-text) !important;
    border: 1px solid var(--ytm-light-border) !important;
    box-shadow: 0 2px 8px rgba(60,64,67,.18) !important;
}


/* =========================================================
   31. SCROLLBARS
   ========================================================= */

::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #ffffff !important;
}

::-webkit-scrollbar-thumb {
    background: #dadce0 !important;
    border-radius: 5px;
}

::-webkit-scrollbar-thumb:hover {
    background: #bdc1c6 !important;
}


/* =========================================================
   32. LINKS
   ========================================================= */

a {
    color: inherit !important;
}


/* =========================================================
   33. REMOVE UI GRADIENTS
   ========================================================= */

ytmusic-app-layout .background-gradient,
ytmusic-browse-response .background-gradient {
    background: linear-gradient(to bottom, #f1f3f4 0%, #ffffff 72%, #ffffff 100%) !important;
}


/* =========================================================
   34. ARTWORK PROTECTION
   ========================================================= */

ytmusic-two-row-item-renderer img,
ytmusic-list-item-renderer img,
ytmusic-responsive-list-item-renderer img,
yt-img-shadow img {
    filter: none !important;
}
}
